<script setup>
import {ref,computed,onUnmounted,watch,nextTick,onMounted} from 'vue';
let profileGeneration=0;
const selectedSkill=ref('breathing-v1'), groundingStep=ref(0);
const groundingSteps=['Notice five things you can see.','Notice four things you can feel.','Notice three things you can hear.','Notice two things you can smell.','Notice one thing you can taste already.'];
const skillName=id=>id==='grounding-v1'?'Sensory grounding':'Breathing';
function chooseSkill(id){selectedSkill.value=id;cancelIntroduction();cancelChat();view.value='setup'}
function nextGrounding(){if(status.value!=='active')return;if(groundingStep.value<4){groundingStep.value++;save()}else{status.value='completed';save().finally(loadProfile)}}

const profileId=ref(localStorage.oneStepProfileId||'alex'), profiles=ref([]), profile=ref(null), profileDraft=ref(null), profileStatus=ref(''), checkState=ref(''), checkNote=ref(''), checkStatus=ref(''), days=ref(null), chosenDate=ref(new Date().toLocaleDateString('en-CA')), monthOffset=ref(0), latestContext=ref(null), compactOverride=ref(null), stateMessage=ref('');
const stateLabels={more_going_on:'More going on',some_room:'Some room',ready:'Ready to begin'};
const currentState=computed(()=>profile.value?.latest_checkin?.state||'');
const effectiveSimple=computed(()=>compactOverride.value ?? (currentState.value==='more_going_on'||simple.value));
const monthDate=computed(()=>new Date(new Date().getFullYear(),new Date().getMonth()+monthOffset.value,1));
const monthLabel=computed(()=>monthDate.value.toLocaleDateString(undefined,{month:'long',year:'numeric'}));
function localDay(value){const date=new Date(value);return date.toLocaleDateString('en-CA')}
const calendarDays=computed(()=>{const d=monthDate.value, first=new Date(d.getFullYear(),d.getMonth(),1).getDay(),total=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();return [...Array(first).fill(null),...Array.from({length:total},(_,i)=>{const date=new Date(d.getFullYear(),d.getMonth(),i+1);const key=date.toLocaleDateString('en-CA');return{day:i+1,key,hasActivity:!!days.value&&[...days.value.sessions,...days.value.checkins,...days.value.conversations].some(r=>localDay(r.created_at)===key)}})]});
const selectedEvents=computed(()=>!days.value?[]:[...days.value.sessions.map(r=>({...r,kind:skillName(r.skill_id),detail:r.status+' · '+(r.active_ms/1000).toFixed(1)+' seconds active'})),...days.value.checkins.map(r=>({...r,kind:'Check-in',detail:stateLabels[r.state]+(r.note?' · '+r.note:'')})),...days.value.conversations.map(r=>({...r,kind:'Conversation',detail:'Saved fictional conversation'}))].filter(r=>localDay(r.created_at)===chosenDate.value).sort((a,b)=>b.created_at.localeCompare(a.created_at)));
async function loadProfile(){const token=++profileGeneration,pid=profileId.value;try{const [list,context]=await Promise.all([api('profiles'),api('profiles/'+pid)]);if(token!==profileGeneration||pid!==profileId.value)return;profiles.value=list;profile.value=context;const p=context.profile;simple.value=p.display_mode==='simple';motion.value=!!p.motion;profileDraft.value={...p,motion:!!p.motion,no_typing:!!p.no_typing};lastSkill.value=null;profileStatus.value='Profile loaded from SQLite'}catch{if(token===profileGeneration)profileStatus.value='Profile unavailable. You can still use breathing and support.'}}
async function switchProfile(){if(view.value==='exercise')stop();profileGeneration++;profile.value=null;lastSkill.value=null;cancelChat();cancelIntroduction();messages.value=[];cid.value=null;latestContext.value=null;checkState.value='';checkNote.value='';checkStatus.value='';compactOverride.value=null;days.value=null;history.value=null;localStorage.oneStepProfileId=profileId.value;view.value='home';await loadProfile()}
async function saveProfile(){const pid=profileId.value;try{await api('profiles/'+pid,{method:'PUT',body:JSON.stringify(profileDraft.value)});if(pid!==profileId.value)return;await loadProfile();profileStatus.value='Profile saved to SQLite';compactOverride.value=null}catch{if(pid===profileId.value)profileStatus.value='Profile not saved. Try again.'}}
async function submitCheckin(){if(!checkState.value)return;try{await api('checkins',{method:'POST',body:JSON.stringify({profile_id:profileId.value,state:checkState.value,note:checkNote.value})});checkStatus.value='Check-in saved';stateMessage.value=checkState.value==='more_going_on'?'You chose More going on, so the entry view is simpler. You can override it below.':'Your check-in was saved. Choose the view that suits this task.';compactOverride.value=null;await loadProfile();view.value='home'}catch{checkStatus.value='Check-in not saved. You can skip it and continue.'}}
function overrideView(){compactOverride.value=!effectiveSimple.value}
async function showDays(){cancelChat();cancelIntroduction();view.value='days';const pid=profileId.value;try{const result=await api('history?profile_id='+pid);if(pid!==profileId.value||view.value!=='days')return;days.value=result;error.value=''}catch{error.value='Calendar unavailable. Exercise and support still work.'}}
function openProfile(){cancelChat();cancelIntroduction();view.value='profile';profileDraft.value=profile.value?{...profile.value.profile,motion:!!profile.value.profile.motion,no_typing:!!profile.value.profile.no_typing}:null}
function goHome(){if(view.value==='exercise')stop();else{cancelChat();cancelIntroduction();view.value='home';loadProfile()}}
const chatConnection=ref(null),shareProfileContext=ref(false);
function newChat(){cancelChat();messages.value=[];cid.value=null;latestContext.value=null;input.value=''}
onMounted(()=>{loadProfile();api('chat-status').then(value=>chatConnection.value=value).catch(()=>chatConnection.value=null)});
const lastSkill=ref(null);
const introMode=ref('mock'), introState=ref('idle'), introText=ref('');
let introController=null,introGeneration=0;
function cancelIntroduction(){introGeneration++;introController?.abort();if(introState.value==='loading')introState.value='idle'}
async function loadIntroduction(){cancelIntroduction();const token=++introGeneration;const request=new AbortController();introController=request;introState.value='loading';const timeout=setTimeout(()=>request.abort(),5000);try{const data=await api('demo-introduction?mode='+introMode.value,{signal:request.signal});if(token!==introGeneration)return;introText.value=data.text;introState.value='ready'}catch{if(token===introGeneration){introState.value='failed';introText.value='Introduction unavailable. You can still choose breathing or open crisis support.'}}finally{clearTimeout(timeout)}}
function chooseBreathing(){chooseSkill('breathing-v1')}
const view=ref('home'), support=ref(false), simple=ref(localStorage.oneStepSimple==='true'), motion=ref(localStorage.oneStepMotion!=='false'), status=ref('ready'), active=ref(0), paused=ref(0), saved=ref(''), history=ref(null), input=ref(''), messages=ref([]), busy=ref(false), cid=ref(null), error=ref('');
let saveQueue=Promise.resolve();
let id=null, start=0, last=0, controller=null, generation=0, pending=null;
const phase=computed(()=>selectedSkill.value==='grounding-v1'?(status.value==='completed'?'Exercise finished.':groundingSteps[groundingStep.value]):active.value>=60000?'Exercise finished.':active.value%10000<4000?'Breathe in':'Breathe out');
const cycle=computed(()=>Math.min(6,Math.floor(active.value/10000)+1));
const count=computed(()=>Math.floor((active.value%10000<4000?active.value%10000:active.value%10000-4000)/1000)+1);
const orbStyle=computed(()=>{const t=active.value%10000;const progress=t<4000?t/4000:1-(t-4000)/6000;return {transform:`scale(${motion.value&&status.value!=='completed'?1+.15*progress:1})`}});
async function api(path,options={}){const r=await fetch('/api/'+path,{...options,headers:{'Content-Type':'application/json'},signal:options.signal||AbortSignal.timeout(5000)});if(!r.ok)throw Error('Request failed');return r.json()}
function prefs(){localStorage.oneStepSimple=simple.value;localStorage.oneStepMotion=motion.value}
async function save(){if(!id)return;const body={id,skill_id:selectedSkill.value,profile_id:profileId.value,status:status.value,active_ms:Math.round(active.value),paused_ms:Math.round(paused.value),wall_ms:Math.round(performance.now()-start),checkpoint:phase.value};pending=body;localStorage.oneStepCheckpoint=JSON.stringify(body); saved.value='Saving…';try{saveQueue=saveQueue.catch(()=>{}).then(()=>api('sessions/'+body.id,{method:'PUT',body:JSON.stringify(body)}));await saveQueue;if(pending===body){saved.value='Saved locally';pending=null;if(['completed','interrupted'].includes(body.status))localStorage.removeItem('oneStepCheckpoint')}}catch{saved.value='Not saved — retry available'}}
async function retry(){if(!pending)return;const body=pending;try{await api('sessions/'+body.id,{method:'PUT',body:JSON.stringify(body)});pending=null;localStorage.removeItem('oneStepCheckpoint');saved.value='Saved locally'}catch{saved.value='Not saved — retry available'}}
function cancelChat(){generation++;controller?.abort();busy.value=false}
function begin(){cancelIntroduction();cancelChat();id=crypto.randomUUID();start=last=performance.now();active.value=paused.value=0;status.value='active';groundingStep.value=0;view.value='exercise';lastSkill.value=skillName(selectedSkill.value);save()}
function pause(){if(status.value==='active'){status.value='paused';save()}}
function resume(){last=performance.now();status.value='active';save()}
function stop(){status.value='interrupted';save().finally(loadProfile);view.value='home'}
function openSupport(){pause();support.value=true}
if(localStorage.oneStepCheckpoint){try{pending={...JSON.parse(localStorage.oneStepCheckpoint),status:'interrupted'};saved.value='Previous session interrupted — retry saving';retry()}catch{localStorage.removeItem('oneStepCheckpoint')}}
watch(support,async value=>{await nextTick();if(value)document.querySelector('.overlay button')?.focus();else document.querySelector('.support')?.focus()});
function trap(event){const list=[...event.currentTarget.querySelectorAll('a,button')];if(event.key==='Escape'){support.value=false;return}if(event.key==='Tab'){if(event.shiftKey&&document.activeElement===list[0]){event.preventDefault();list.at(-1).focus()}else if(!event.shiftKey&&document.activeElement===list.at(-1)){event.preventDefault();list[0].focus()}}}
let animationFrame;
function tick(t){const d=t-last;last=t;if(view.value==='exercise'){if(status.value==='active'){if(d>1500||document.hidden){pause()}else{active.value=selectedSkill.value==='grounding-v1'?active.value+d:Math.min(60000,active.value+d);if(selectedSkill.value==='breathing-v1'&&active.value>=60000){status.value='completed';save().finally(loadProfile)}}}else if(status.value==='paused')paused.value+=d}animationFrame=requestAnimationFrame(tick)}
animationFrame=requestAnimationFrame(tick);
const checkpoint=setInterval(()=>{if(view.value==='exercise'&&['active','paused'].includes(status.value))save()},2000);
function visibility(){if(document.hidden)pause()};document.addEventListener('visibilitychange',visibility);
onUnmounted(()=>{cancelAnimationFrame(animationFrame);clearInterval(checkpoint);document.removeEventListener('visibilitychange',visibility)});
async function showHistory(){cancelChat();view.value='history';error.value='';const pid=profileId.value;try{const result=await api('history?profile_id='+pid);if(pid===profileId.value&&view.value==='history')history.value=result}catch{error.value='History unavailable. Exercise and support remain available.'}}
async function clear(){const pid=profileId.value;try{await api('history?profile_id='+pid,{method:'DELETE'});if(pid!==profileId.value)return;cancelChat();messages.value=[];cid.value=null;latestContext.value=null;pending=null;localStorage.removeItem('oneStepCheckpoint');lastSkill.value=null;await loadProfile();await showHistory()}catch{error.value='Could not delete history. Try again.'}}
async function send(){if(!input.value.trim()||busy.value)return;const text=input.value;input.value='';messages.value.push({role:'You',text});busy.value=true;const token=++generation;controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),35000);try{const r=await api('messages',{method:'POST',body:JSON.stringify({text,conversation_id:cid.value,profile_id:profileId.value,display_mode:effectiveSimple.value?'simple':'full',include_profile_context:shareProfileContext.value}),signal:controller.signal});if(token!==generation)return;cid.value=r.conversation_id;latestContext.value=r.personalization;messages.value.push({role:'Prototype · '+r.status,text:r.text});api('chat-status').then(value=>chatConnection.value=value).catch(()=>{});if(r.crisis)openSupport()}catch{if(token===generation)messages.value.push({role:'Prototype',text:'Chat unavailable. Exercises and crisis support are still available.'})}finally{clearTimeout(timeout);if(token===generation)busy.value=false}}
</script>
<template>
<div class="shell preview" :class="{compact:effectiveSimple}" :inert="support">
<header><a href="#" @click.prevent="goHome" class="brand"><span class="brand-mark" aria-hidden="true">◒</span> One Step</a><button class="support" @click="openSupport">Crisis support</button></header>
<p class="preview-tag">FICTIONAL COURSEWORK DEMO · ONE STEP</p><p class="notice">Coursework skills prototype. Fictional scenarios only. This is not therapy or a monitored service.</p>
<div v-if="view!=='exercise'" class="profile-strip"><span>Fictional profile</span><label class="sr-only" for="active-profile">Active fictional profile</label><select id="active-profile" v-model="profileId" @change="switchProfile"><option v-for="p in profiles" :key="p.id" :value="p.id">{{p.name}}</option></select><button @click="openProfile">Edit preferences</button></div>
<main><p v-if="view!=='exercise' && pending && saved.includes('retry')" role="status">{{saved}} <button @click="retry">Retry saving</button></p>
<template v-if="view==='home'">
<div class="welcome-art" aria-hidden="true"><svg viewBox="0 0 280 160" fill="none"><circle cx="191" cy="55" r="32" fill="#EBC58C"/><path d="M10 144C55 75 105 70 160 119C200 155 234 99 280 107V160H10Z" fill="#D8E3DA"/><path d="M0 155C65 127 99 166 155 133C204 104 244 127 280 138V160H0Z" fill="#AFC9BE"/><path d="M115 149C116 118 128 96 149 79M129 111C107 112 100 97 100 88C120 86 132 94 129 111ZM140 91C138 71 151 59 165 58C167 77 158 88 140 91Z" stroke="#3F6A58" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></svg></div><p class="eyebrow">A LITTLE SPACE, AT YOUR PACE</p><h1>{{profile?profile.profile.name+', one step at a time.':'One step at a time.'}}</h1>
<p class="welcome-copy">There’s no rush. Take a moment, or begin with one small step.</p><p v-if="profile && !effectiveSimple" class="goal">Your fictional goal: {{profile.profile.goal}}</p>

<p v-if="currentState" class="adaptation" role="status">Your check-in suggests {{currentState==='more_going_on'?'a simpler view':'your usual view'}}. You are using {{effectiveSimple?'simpler':'full'}} view. <button @click="overrideView">{{effectiveSimple?'Show full view':'Use simpler view'}}</button></p>
<div class="skill-grid"><section class="skill-card" aria-labelledby="skill-title"><div><h2 id="skill-title"><span class="skill-symbol" aria-hidden="true">◌</span> Breathing</h2><span class="duration">About 60 seconds </span></div><p>A short, guided rhythm with room to pause.<br>No typing or speaking required.</p><button class="primary choose" @click="chooseBreathing">Choose breathing exercise <span aria-hidden="true">→</span></button><small>You choose when to start. Pause or stop at any time.</small></section>
<section class="skill-card grounding-card" aria-labelledby="grounding-title"><h2 id="grounding-title"><span class="skill-symbol" aria-hidden="true">✧</span> Sensory grounding</h2><span class="duration">Self-paced · five senses · skip any step</span><p>Notice what is around you, one sense at a time. No breathing rhythm or typed answers.</p><button class="primary choose" @click="chooseSkill('grounding-v1')">Choose grounding exercise <span aria-hidden="true">→</span></button><small>You choose each next step. Nothing starts automatically.</small></section>
</div><section class="checkin-card"><div><h2>How much room do you have right now?</h2><p>{{currentState?'Last choice: '+stateLabels[currentState]:'You can share a little, or begin without answering.'}}</p></div><button @click="checkState=currentState;checkNote='';view='checkin'">{{currentState?'Change check-in':'Check in'}}</button></section><p v-if="!effectiveSimple" class="secondary-copy">Choose a timed breathing rhythm or self-paced sensory prompts. Both keep one instruction at a time.</p>
<p v-if="profile && !effectiveSimple" class="history-hint">Saved for this profile: {{profile.usage.completed||0}} completed · {{profile.usage.interrupted||0}} stopped. These are activity records, not progress scores.</p>
<div v-if="!currentState" class="view-choice"><span>Current view: {{effectiveSimple?'Simpler':'Full'}}</span><button @click="overrideView">{{effectiveSimple?'Switch to full view':'Switch to simpler view'}}</button></div>
<details :open="!effectiveSimple"><summary>More options</summary><section class="demo"><details><summary>Demo test tools</summary><h2>Introduction demo</h2><p>Mocked explanation only. Not saved to history. No live model call.</p><label for="intro-mode">Demo response mode</label><select id="intro-mode" v-model="introMode" @change="cancelIntroduction();introState='idle'"><option value="mock">Mock</option><option value="failed">Failed</option><option value="delayed">Delayed · 3 seconds</option></select><button @click="loadIntroduction">{{introState==='idle'?'Load mock introduction':'Retry mock introduction'}}</button><p role="status">{{introState==='loading'?'Waiting for mocked introduction…':introText}}</p></details></section><nav><button @click="view='chat'">Chat with One Step</button><button @click="showHistory">Saved history</button><button @click="showDays">Your days</button></nav></details>
</template>
<template v-else-if="view==='checkin'"><p class="eyebrow">OPTIONAL · YOUR OWN CHOICE</p><h1>A quick check-in.</h1><p>This is a display preference for this moment, not an assessment. More going on suggests the simpler entry view. You can override it.</p><fieldset><legend>How much room do you have?</legend><label v-for="(label,key) in stateLabels" :key="key" class="state-option"><input type="radio" name="state" :value="key" v-model="checkState"> {{label}}</label></fieldset><label for="check-note">Fictional note (optional)</label><textarea id="check-note" maxlength="200" v-model="checkNote" placeholder="Example: before a made-up class presentation"></textarea><p role="status">{{checkStatus}}</p><button class="primary" :disabled="!checkState" @click="submitCheckin">Save check-in</button><button @click="view='home'">Skip for now</button></template>
<template v-else-if="view==='profile'"><p class="eyebrow">EXPLICIT CHOICES · SAVED LOCALLY</p><h1>Your fictional profile.</h1><form v-if="profileDraft" @submit.prevent="saveProfile"><label for="profile-name">Fictional name</label><input id="profile-name" v-model="profileDraft.name" maxlength="40" required><label for="profile-goal">Fictional goal</label><input id="profile-goal" v-model="profileDraft.goal" maxlength="140" required><label for="profile-view">Default display</label><select id="profile-view" v-model="profileDraft.display_mode"><option value="full">Full view</option><option value="simple">Simpler view</option></select><label><input type="checkbox" v-model="profileDraft.motion"> Gentle motion</label><label><input type="checkbox" v-model="profileDraft.no_typing"> Prefer no typing during exercises</label><button class="primary">Save profile</button></form><p role="status">{{profileStatus}}</p><p>SQLite stores these choices, your check-ins, fictional chat, and exercise history for this profile. You can change any preference. We do not save a diagnosis, infer distress, or treat a stopped exercise as failure.</p><button @click="view='home'">Back</button></template>
<template v-else-if="view==='days'"><p class="eyebrow">SAVED ACTIVITY · NO SCORES OR STREAKS</p><h1>Your days.</h1><p>{{profile?.profile.name}}’s check-ins, exercises, and conversations. Dates use this browser’s local time.</p><p role="alert">{{error}}</p><div class="month-bar"><button aria-label="Previous month" @click="monthOffset--">←</button><h2>{{monthLabel}}</h2><button aria-label="Next month" @click="monthOffset++">→</button></div><div class="calendar"><span v-for="day in ['Sun','Mon','Tue','Wed','Thu','Fri','Sat']" :key="day">{{day}}</span><template v-for="(d,i) in calendarDays" :key="i"><button v-if="d" :aria-label="d.key+(d.hasActivity?' · saved activity':'')" :aria-pressed="chosenDate===d.key" :class="{selected:chosenDate===d.key,hasActivity:d.hasActivity}" @click="chosenDate=d.key">{{d.day}}<span aria-hidden="true">{{d.hasActivity?'•':''}}</span></button><span v-else></span></template></div><h2>{{chosenDate}}</h2><p v-if="!selectedEvents.length">No saved activity on this date.</p><article v-for="event in selectedEvents" :key="event.id"><strong>{{event.kind}}</strong><p>{{event.detail}}</p><small>{{new Date(event.created_at).toLocaleTimeString()}}</small></article><button @click="showHistory">Open saved transcripts and sessions</button><button @click="view='home'">Back</button></template>
<template v-else-if="view==='setup'"><p class="eyebrow">BEFORE YOU START</p><h1>{{skillName(selectedSkill)}}</h1><template v-if="selectedSkill==='breathing-v1'"><p>Six cycles: breathe in for four counts, then out for six. The first inhale begins as soon as you press Start. You can pause or stop immediately. No breath holds. Skip this exercise if it feels uncomfortable.</p><label><input type="checkbox" v-model="motion" @change="prefs"> Gentle motion (respects reduced motion settings)</label></template><p v-else>Five prompts, at your own pace: see, feel, hear, smell, taste. Notice only what is already available. Do not seek out or taste anything new. Use Next or Skip this sense, or stop whenever you choose. No typing, speaking, or fixed time limit.</p><p>Sessions and optional fictional chat are saved on this computer. History lets you review and clear them. Refresh resets exercise progress; the previous saved checkpoint is recorded as interrupted.</p><button class="primary" @click="begin">Start exercise</button><button @click="view='home'">Back</button></template>
<template v-else-if="view==='exercise'"><section class="exercise-stage"><p class="eyebrow">{{status==='paused'?'PAUSED':status==='completed'?'COMPLETE':selectedSkill==='grounding-v1'?`SENSE ${groundingStep+1} OF 5`:`CYCLE ${cycle} OF 6`}}</p><h1 aria-live="polite">{{phase}}</h1><div v-if="selectedSkill==='breathing-v1'" class="orb" :style="orbStyle">{{status==='completed'?'✓':count}}</div><template v-if="selectedSkill==='grounding-v1' && status!=='completed'"><p>No answers are recorded. Skip any sense that is unavailable or uncomfortable.</p><div class="grounding-actions"><button class="primary" :disabled="status!=='active'" @click="nextGrounding">{{groundingStep===4?'Finish exercise':'Next sense'}}</button><button :disabled="status!=='active'" @click="nextGrounding">Skip this sense</button></div></template><p class="timing">{{Math.floor(active/1000)}} seconds active · {{Math.floor(paused/1000)}} paused</p><nav class="exercise-controls" v-if="status!=='completed'"><button @click="status==='paused'?resume():pause()">{{status==='paused'?'Resume':'Pause'}}</button><button @click="stop">Stop</button></nav><button v-else @click="view='home'">Done</button><p class="save-status" role="status">{{saved}}</p><button v-if="pending && saved.includes('retry')" @click="retry">Retry saving</button></section></template>
<template v-else-if="view==='chat'"><p class="eyebrow">A CONVERSATION, AT YOUR PACE</p><h1>Chat with One Step</h1><p>Ask a question, explore an idea, get help with writing or learning, or simply have a conversation. Follow-up questions stay in this chat.</p><p class="connection-status" role="status">{{chatConnection?.mode==='live'?(chatConnection.available?'Live AI · general conversation · replies can make mistakes.':'Live chatbot needs setup · no model is connected yet.'):'Demo mode · replies use a limited set of presets.'}}</p><p class="chat-disclosure">Use fictional examples only. Live chat sends up to 12 recent messages from this conversation to OpenAI. Profile and activity context is optional. No web browsing or current-information verification. This is a coursework prototype, not a therapist or monitored service.</p><label class="context-toggle"><input type="checkbox" v-model="shareProfileContext"> Include fictional profile and saved activity in replies</label><section v-if="profile && shareProfileContext" class="chat-context"><strong>Context you control</strong><p>{{profile.profile.name}} · {{profile.profile.goal}} · {{effectiveSimple?'simpler':'full'}} current display · {{profile.usage.completed||0}} completed / {{profile.usage.interrupted||0}} stopped. Last check-in: {{stateLabels[profile.latest_checkin?.state]||'none'}}.</p><button @click="openProfile">Correct these preferences</button></section><div v-if="!messages.length" class="prompt-row"><button @click="input='Help fictional Alex plan a 30-minute study session.'">Plan a study session</button><button @click="input='Explain why the sky looks blue in simple terms.'">Explain something</button><button @click="shareProfileContext=true;input='What does my saved history show?'">Ask about my history</button></div><section class="chat-log" role="log" aria-label="Conversation" aria-live="polite" :aria-busy="busy"><article v-if="!messages.length" class="chat-bubble"><strong>One Step</strong><p>Hi! What would you like to talk about? In live AI mode, you can ask general questions or follow up on an idea. Demo mode uses preset app replies.</p></article><article v-for="(m,i) in messages" :key="i" class="chat-bubble" :class="{'from-you':m.role==='You'}"><strong>{{m.role==='You'?'You':m.role.replace('Prototype','One Step')}}</strong><p>{{m.text}}</p></article><p v-if="busy" role="status">One Step is replying…</p></section><form class="chat-composer" @submit.prevent="send"><label for="message">Your message (fictional examples only)</label><textarea id="message" v-model="input" maxlength="2000" placeholder="Ask a question, explore an idea, or describe a fictional scenario…" :disabled="chatConnection?.mode==='live'&&!chatConnection.available"></textarea><button class="primary" :disabled="busy||!input.trim()||(chatConnection?.mode==='live'&&!chatConnection.available)">{{busy?'Replying…':'Send message'}}</button></form><details v-if="latestContext"><summary>Why this response?</summary><p v-if="latestContext.profile_context_included!==false">The response was given this profile’s explicit preferences and counts of saved activity. Older conversation transcripts were excluded. Last check-in: {{stateLabels[latestContext.latest_checkin?.state]||'none'}}. These records are not a mood assessment.</p><p v-else>Profile and saved-activity context was not sent with this response. Recent messages in this conversation were included. Earlier messages already sent may still contain details you shared; start a new chat to clear that conversational context.</p></details><button @click="newChat" :disabled="busy || !messages.length">New chat</button><button @click="chooseBreathing">Choose breathing</button><button @click="cancelChat();view='home'">Back</button></template>
<template v-else-if="view==='history'"><h1>Saved history</h1><p role="alert">{{error}}</p><template v-if="history"><h2>Exercises</h2><p v-if="!history.sessions.length">No saved exercises.</p><article v-for="s in history.sessions" :key="s.id"><strong>{{skillName(s.skill_id)}} · {{s.status}}</strong><p>{{s.created_at}} · {{(s.active_ms/1000).toFixed(1)}} seconds active · {{(s.paused_ms/1000).toFixed(1)}} paused · {{(s.wall_ms/1000).toFixed(1)}} elapsed</p></article><h2>Conversations</h2><details v-for="c in history.conversations" :key="c.id"><summary>{{c.created_at}}</summary><article v-for="m in [...history.messages].reverse().filter(m=>m.conversation_id===c.id)" :key="m.id"><strong>{{m.role}} · {{m.status}}</strong><p>{{m.text}}</p><small v-if="m.role==='assistant'">{{m.model_id}} · Context {{m.context_ids}}</small></article></details><button @click="clear">Clear this profile’s history</button></template><button @click="view='home'">Back</button></template>
</main><nav v-if="view!=='exercise'" class="bottom-nav" aria-label="Main navigation"><button :aria-current="view==='home'?'page':undefined" @click="goHome">Home</button><button :aria-current="view==='setup'?'page':undefined" @click="goHome">Practice</button><button :aria-current="view==='chat'?'page':undefined" @click="cancelIntroduction();view='chat'">Chat</button><button :aria-current="view==='days'?'page':undefined" @click="showDays">Your days</button><button :aria-current="view==='profile'?'page':undefined" @click="openProfile">Profile</button></nav><footer>Local coursework prototype · No one monitors this app.</footer>
</div>
<div v-if="support" class="overlay" @keydown="trap"><section role="dialog" aria-modal="true" aria-label="Crisis support" tabindex="-1"><h2>Crisis support · United States</h2><p>This prototype cannot assess safety or provide crisis care.</p><p>988 Suicide &amp; Crisis Lifeline: <a href="tel:988?oai_link_source=model_response_hotline">call 988</a> or <a href="sms:988?oai_link_source=model_response_hotline">text 988</a>.</p><p><a href="https://988lifeline.org/chat/?oai_link_source=model_response_hotline">Online chat</a> · <a href="https://988lifeline.org?oai_link_source=model_response_hotline">988 Lifeline website</a></p><p>Outside the United States, contact a local crisis service or local emergency services. Calls, texts, and websites require their respective services. This panel opens without the backend or a model decision.</p><button autofocus @click="support=false">Close support</button><button v-if="view==='exercise' && status==='paused'" @click="stop();support=false">Stop exercise</button><p v-if="status==='paused'">Your exercise stays paused until you choose Resume.</p></section></div>
</template>
<style>
:root{font-family:system-ui,sans-serif;color:#263d38;background:#f4f5ef;font-synthesis:none}*{box-sizing:border-box}body{margin:0}button,a,input,summary{touch-action:manipulation}button{font:inherit;border:1px solid #71857c;border-radius:12px;background:#fff;color:#263d38;padding:13px 20px;cursor:pointer;margin:5px}button:hover{background:#e5ede7}button:focus-visible,a:focus-visible,summary:focus-visible{outline:3px solid #93621c;outline-offset:3px}.shell{max-width:850px;margin:auto;padding:25px}header{position:sticky;top:0;z-index:3;background:#f4f5ef;padding:8px 0;display:flex;align-items:center;justify-content:space-between;gap:8px}.brand{font-size:24px;text-decoration:none;color:inherit}.support{border-color:#8b5440;color:#713d2e}.notice{font-size:13px;border-block:1px solid #c9d2c9;padding:15px 0;line-height:1.6}main{min-height:65vh;padding:45px 0}h1{font-family:Georgia,serif;font-weight:400;font-size:clamp(32px,6vw,49px);line-height:1.2}p{line-height:1.7;max-width:65ch}.eyebrow{font-size:12px;letter-spacing:2px}.card{display:flex;width:100%;max-width:640px;justify-content:space-between;text-align:left;padding:30px 22px;margin:32px 0;background:#e4ece3;gap:20px}.card span:first-child{font-size:22px}.card small{font-size:12px}.muted,footer{color:#52645b;font-size:14px}details{margin:20px 0}summary{cursor:pointer;padding:12px 0}nav{background:#f4f5ef;padding:8px 0;display:flex;flex-wrap:wrap;gap:8px}.primary{background:#285f50;color:white}label{display:block;margin:15px 0}.orb{width:165px;height:165px;border-radius:100%;background:#d6e4d8;display:grid;place-items:center;font-size:25px;margin:45px auto}textarea{width:100%;min-height:100px;font:inherit;padding:12px;border-radius:8px}article{border-bottom:1px solid #ccd5cc;padding:15px 0;overflow-wrap:anywhere}.overlay{position:fixed;inset:0;background:#182b2588;display:grid;place-items:center;padding:20px;z-index:5}.overlay section{background:#fff;border-radius:20px;padding:28px;max-width:600px;max-height:90dvh;overflow:auto}a{color:#215d4b}footer{padding:20px 0}@media(prefers-reduced-motion:reduce){.orb{transition:none;transform:none}}@media(max-width:450px){.shell{padding:15px}.card{flex-direction:column}main{padding-top:20px}}

.exercise-controls{position:sticky;bottom:0}.skill-card{max-width:640px;border:1px solid #a9bcae;border-radius:20px;background:#e4ece3;padding:28px;margin:28px 0}.skill-card h2{font:400 30px Georgia,serif;margin:0 0 10px}.duration{font-size:14px}.skill-card p{margin:18px 0}.choose{display:flex;justify-content:space-between;align-items:center;width:100%;margin:0 0 16px;padding:17px 20px}.skill-card small{display:block;line-height:1.6}.duration small{display:inline}.secondary-copy{color:#52645b}.demo{border-top:1px solid #c9d2c9;padding-top:12px}.demo h2{font-size:17px}.demo p{font-size:14px}select{font:inherit;color:inherit;background:white;border:1px solid #71857c;border-radius:8px;padding:12px}select:focus-visible,textarea:focus-visible,input:focus-visible{outline:3px solid #93621c;outline-offset:3px}@media(max-width:450px){.skill-card{padding:20px}.demo button{margin-left:0}}

.preview-tag{font-size:12px;color:#795219;letter-spacing:1px}.profile-strip{display:flex;gap:12px;align-items:center;flex-wrap:wrap;border-bottom:1px solid #c9d2c9;padding:12px 0}.profile-strip span{font-size:13px}.profile-strip button{padding:9px 13px}.checkin-card{display:flex;gap:20px;align-items:center;justify-content:space-between;border:1px solid #d6c8b8;background:#f1e7dd;border-radius:16px;padding:18px;max-width:640px}.checkin-card h2{font-size:17px;margin:0}.checkin-card p{font-size:14px;margin:8px 0 0}.adaptation{background:#e4ece3;padding:15px;border-radius:12px;font-size:14px}.adaptation button{padding:8px}.view-choice{display:flex;align-items:center;gap:15px;font-size:14px}.history-hint{font-size:14px;color:#52645b}.goal{font-size:16px}.bottom-nav{position:sticky;bottom:0;display:flex;justify-content:space-between;gap:0;border-top:1px solid #c9d2c9;z-index:2}.bottom-nav button{font-size:14px;padding:12px 8px;margin:2px;border-color:transparent}.month-bar{display:flex;align-items:center;justify-content:space-between}.month-bar h2{font-size:20px}.calendar{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:5px;max-width:640px}.calendar>span{font-size:12px;text-align:center;padding:10px 0}.calendar button{margin:0;min-height:57px;padding:8px;display:flex;flex-direction:column;align-items:center;border-color:#c9d2c9}.calendar button.selected{background:#285f50;color:white}.calendar button span{min-height:12px}.chat-context{border:1px solid #c9d2c9;background:#e4ece3;padding:18px;border-radius:16px}.chat-context p{font-size:14px}.prompt-row{display:flex;flex-wrap:wrap;margin:18px 0}.state-option{padding:15px;background:white;border:1px solid #c9d2c9;border-radius:12px}fieldset{border:0;padding:0}input:not([type=checkbox]):not([type=radio]){display:block;width:100%;padding:13px;font:inherit;border:1px solid #71857c;border-radius:8px}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}.compact .skill-card{margin-top: