/* Warm paper, sage growth, and a small sunrise: quiet landmarks, not scores. */
:root{color:#29483f;background:#f8f5ee;font-family:"Avenir Next","Segoe UI",sans-serif;background-image:radial-gradient(ellipse at 7% 20%,#e8eee3 0,transparent 44%),radial-gradient(ellipse at 95% 68%,#f4e7d4 0,transparent 40%)}
.shell{max-width:920px;padding:24px 40px}header{background:#f8f5eef5;backdrop-filter:blur(12px);border-bottom:1px solid #dce2d7;padding:12px 0}.brand{font-weight:600;letter-spacing:-.7px;display:flex;align-items:center;gap:10px}.brand-mark{display:grid;place-items:center;width:39px;height:39px;border-radius:50% 50% 44% 44%;background:#d8e5d9;color:#35614e;font-size:28px}.support{background:#fffaf4;border-color:#b4826a;color:#78422f;font-size:14px}.preview-tag{margin-bottom:5px;font-size:10px;letter-spacing:1.4px;color:#6d604b}.notice{border:0;padding:0;margin:0 0 14px;color:#58675c;font-size:12px}.profile-strip{background:#ffffff75;border:1px solid #dce2d7;padding:10px 14px;border-radius:16px;font-size:13px}.profile-strip select{padding:8px 12px}.profile-strip button{margin-left:auto;background:transparent;border-color:transparent;text-decoration:underline;text-underline-offset:4px}
main{position:relative;padding-top:36px}h1{letter-spacing:-1.5px;margin:12px 0 18px;max-width:620px}.eyebrow{color:#54725e;font-size:11px;font-weight:600;letter-spacing:1.7px}.welcome-art{float:right;width:190px;margin:8px 0 4px 12px;pointer-events:none}.welcome-art svg{width:100%;height:auto}.welcome-copy{font-size:18px;color:#4e675b;max-width:43ch;margin:0 0 18px}.goal{font-size:13px;color:#617064;margin-bottom:26px}
button{border-color:#8b9f91;border-radius:14px;min-height:44px;transition:background .15s}button:hover{background:#e8eee3}.primary{background:#315e4e;border-color:#315e4e;color:#fff}.primary:hover{background:#234b3c;color:#fff}.checkin-card{clear:both;background:#f4ead9;border-color:#e3d4bc;border-radius:22px;padding:22px;max-width:100%}.checkin-card h2{font-weight:600;color:#584d3c}.checkin-card p{color:#6c604d}.checkin-card button{background:#fffaf2;border-color:#ab9270;white-space:nowrap}.skill-card{position:relative;max-width:100%;padding:30px;background:linear-gradient(120deg,#edf3e9,#e0ece2);border-color:#b9cebb;border-radius:28px 28px 28px 8px;box-shadow:0 8px 24px #325c4210}.skill-card h2{display:flex;gap:12px;align-items:center;font-size:32px}.skill-symbol{background:#f8fbf4;border:1px solid #b9cebb;border-radius:50%;width:46px;height:46px;display:inline-grid;place-items:center;font:32px Georgia,serif}.duration{color:#486650}.skill-card p{color:#405f4c}.skill-card small{color:#4c6554}.choose{max-width:460px}.secondary-copy,.history-hint{font-size:13px}.adaptation{background:#e7eee0;border:1px solid #cad8bf}.bottom-nav{background:#fffcf5f5;border:1px solid #d7dfd0;border-radius:20px;margin-top:12px;padding:6px;box-shadow:0 -4px 20px #29483f08;bottom:12px}.bottom-nav button{flex:1;border-radius:12px;color:#506356}.bottom-nav button[aria-current=page]{background:#dfeadb;color:#29483f;font-weight:600}.orb{background:radial-gradient(circle at 35% 30%,#eff5e5,#bfd7c2);border:1px solid #aac7af;box-shadow:0 0 0 16px #dce9d54d;color:#31573e}.exercise-controls{border-radius:18px;background:#f8f5eef5}.chat-context{background:#edf2e7;border-color:#ccd9c4;border-radius:22px}.state-option{background:#fffcf6;border-color:#cbd7c4}.state-option:has(input:checked){background:#e6eedf;border-color:#5f8067}textarea,input:not([type=checkbox]):not([type=radio]),select{background:#fffdf8;border-color:#8b9f91}footer{text-align:center;font-size:12px;color:#617064}.compact .welcome-art{display:none}.compact .welcome-copy{font-size:16px}.compact .skill-card{box-shadow:none}
@media(max-width:600px){.shell{padding:16px 20px}.welcome-art{width:115px;margin-top:12px}h1{font-size:36px}.welcome-copy{font-size:16px}.checkin-card{padding:18px}.skill-card{padding:22px}.profile-strip button{margin-left:0}.bottom-nav{bottom:6px}.bottom-nav button{font-size:12px;padding:12px 4px}}
