.exercise-stage{text-align:center}.exercise-stage h1{min-height:2.4em;margin:12px auto 18px}.exercise-stage .orb{transition:none;will-change:transform;font-variant-numeric:tabular-nums}.exercise-stage .timing,.save-status{min-height:1.7em;margin-inline:auto;font-variant-numeric:tabular-nums}.exercise-stage .exercise-controls{justify-content:center}.exercise-stage .exercise-controls button{min-width:100px}@media(prefers-reduced-motion:reduce){.exercise-stage .orb{transform:none!important}}
.chat-log{margin:22px 0;display:flex;flex-direction:column;gap:14px}.chat-bubble{border:1px solid #d4dfce;border-radius:20px 20px 20px 5px;background:#fffdf7;padding:18px 22px;max-width:90%}.chat-bubble p{margin:8px 0 0;white-space:pre-wrap}.chat-bubble.from-you{align-self:flex-end;background:#e4eddf;border-radius:20px 20px 5px 20px}.chat-composer{padding:18px;border:1px solid #cbd8c4;border-radius:20px;background:#ffffff80}.chat-composer label{margin-top:0}.chat-disclosure{font-size:12px;color:#58675c}.connection-status{font-size:14px;color:#315e4e;font-weight:600}
.grounding-card{background:linear-gradient(120deg,#f6edde,#eee2cd);border-color:#d4c09d}.grounding-card .skill-symbol{border-color:#d4c09d;background:#fffaf1}.grounding-actions{display:flex;justify-content:center;flex-wrap:wrap;margin:28px 0}.compact .skill-card p{display:none}.compact .skill-card{padding:20px}.compact .skill-card h2{font-size:27px}
.skill-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;clear:both;margin:24px 0}.skill-grid .skill-card{margin:0;padding:22px;display:flex;flex-direction:column}.skill-grid .skill-card h2{font-size:27px;letter-spacing:-.5px}.skill-grid .skill-card p{font-size:15px;flex:1}.skill-grid .choose{padding:14px;text-align:left;gap:8px}.skill-grid .skill-symbol{flex-shrink:0;width:38px;height:38px}.skill-grid .duration{font-size:13px}.compact .skill-grid .skill-card small{display:none}.compact .skill-grid .choose{margin-top:18px}main:has(.skill-grid){padding-top:22px}main:has(.skill-grid) h1{font-size:clamp(30px,5vw,42px)}.checkin-card{margin-top:18px}@media(max-width:650px){.skill-grid{grid-template-columns:1fr;gap:14px}.skill-grid .skill-card{padding:18px}.skill-grid .skill-card p{margin:12px 0}.skill-grid .skill-card h2{font-size:26px}.welcome-art{width:85px}}
